package com.vit.archds.security; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwt; private final CustomUserDetailsService users; public JwtAuthFilter(JwtService j,CustomUserDetailsService u){jwt=j;users=u;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){try{String token=h.substring(7),email=jwt.extractUsername(token);if(email!=null&&SecurityContextHolder.getContext().getAuthentication()==null){UserDetails u=users.loadUserByUsername(email);if(jwt.valid(token,u))SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,u.getAuthorities()));}}catch(Exception ignored){}}chain.doFilter(req,res);}}
